612	// duplicateField returns the first field name appearing more than once.
613	func duplicateField(fields []objectField) (string, bool) {
614		seen := make(map[string]struct{}, len(fields))
615		for _, f := range fields {
616			if _, dup := seen[f.key]; dup {
617				return f.key, true
618			}
619			seen[f.key] = struct{}{}
620		}
621		return "", false
622	}
623	
624	// findField returns the raw value of the first member named name.
625	func findField(fields []objectField, name string) (json.RawMessage, bool) {
626		for _, f := range fields {
627			if f.key == name {
628				return f.value, true
629			}
630		}
631		return nil, false
632	}
633	
634	// countField counts the members named name.
635	func countField(fields []objectField, name string) int {
636		n := 0
637		for _, f := range fields {
638			if f.key == name {
639				n++
640			}
641		}
642		return n
643	}
