		t.Errorf("PrevPos = %d, want 0: no manifest record is the source", ce.PrevPos)
	}
	if strings.Join(ce.Fields, ",") != "quantity" {
		t.Errorf("fields = %v, want [quantity]", ce.Fields)
	}
